package com.shipflow.warehouse;import com.shipflow.warehouse.application.*;import com.shipflow.warehouse.mapper.*;import com.shipflow.order.domain.model.*;import com.shipflow.warehouse.api.model.*;import org.junit.jupiter.api.Test;import java.math.*;import java.time.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WarehouseApplicationServiceTest{@Test void rejectsInboundOutsidePendingInbound(){WarehouseMapper m=mock(WarehouseMapper.class);when(m.findOrder(7L,1L)).thenReturn(new ShipmentOrder(1L,7L,"O","k",1L,1L,1L,"DRAFT","CN","US",BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.ONE,"USD",0L,LocalDateTime.now()));var s=new WarehouseApplicationService(m,Clock.systemUTC());assertThatThrownBy(()->s.inbound(7L,2L,1L,new InboundRequest(0L),null)).isInstanceOf(WarehouseException.class).satisfies(e->assertThat(((WarehouseException)e).code()).isEqualTo("WAREHOUSE-1001"));}}
